INSERT INTO `haberler` (`id`, `baslik`, `detay`, `resim`, `tarih`) VALUES
(1, 'Gebze’de Yaz Konserleri Coşkusu', 'Gebze’de Yaz Konserleri Coşkusu\r\n\r\nGebze Belediyesi tarafından düzenlenen Yaz Konserleri kapsamında Ceyhun Can ve Mustafa Özden, Gebze Millet Bahçesi’nde sahne aldı.\r\n\r\n\r\n\r\nYaz akşamlarının keyfini müzikle buluşturan Gebze Belediyesi, Gebze Millet Bahçesi’nde vatandaşlara unutulmaz bir konser akşamı yaşattı. 16 Ağustos Pazar günü gerçekleştirilen programda Ceyhun Can ve Mustafa Özden, sevilen eserleriyle Gebzelilerle buluştu.\r\n\r\n\r\n\r\nŞarkılar ve Halaylarla Dolu Gece\r\n\r\nSaat 20.00’de başlayan konserde sanatçıların seslendirdiği şarkılara vatandaşlar hep birlikte eşlik etti. Müzik ve eğlencenin bir arada yaşandığı gecede Gebzeliler, aileleri ve sevdikleriyle birlikte keyifli vakit geçirdi. Konser boyunca vatandaşlar şarkılara eşlik ederken, halaylarla da gecenin coşkusuna ortak oldu.\r\n\r\n\r\n\r\nYaz Akşamları Kültür ve Sanatla Buluşuyor\r\n\r\nGebze Belediyesi, yaz döneminde düzenlediği kültür ve sanat etkinlikleriyle vatandaşları açık hava programlarında buluşturmaya devam ediyor. Gebze Millet Bahçesi’nde gerçekleştirilen Yaz Konserleri de kentin sosyal yaşamına renk katan etkinliklerden biri olarak vatandaşlardan ilgi gördü.\r\n\r\n\r\n\r\nMüzik dolu gecenin sonunda vatandaşlar, sanatçılara ve programın düzenlenmesinde emeği geçenlere teşekkür etti.', 'img/haberler/yaz-konseri17.jpg', '2026-08-17 20:00:00'),
(3, 'Başkan Büyükgöz\'den Mecliste Müjde', 'Başkan Büyükgöz\'den Mecliste Müjde\r\n\r\nAğustos Ayı Meclis Toplantısında Öğrencilere Destek Kararı\r\n\r\nGebze Belediyesi Ağustos Ayı Olağan Meclis Toplantısı, Gebze Belediye Başkanı Zinnur Büyükgöz başkanlığında Meclis Toplantı Salonu\'nda gerçekleştirildi.Yoklama ve bir önceki aya ait karar özetlerinin oylanmasıyla başlayan toplantıda, gündemde yer alan maddeler meclis üyelerinin görüşüne sunularak karara bağlandı.Toplantının en dikkat çeken gündem maddelerinden biri ise üniversiteyi ilk kez kazanan gençlere verilecek eğitim desteği oldu.\r\n\r\nBaşkan Büyükgöz\'den Yüzde 20 Artış Teklifi\r\n\r\nSosyal Destek Hizmetleri Müdürlüğü\'nün, geçtiğimiz yıl olduğu gibi üniversiteyi ilk kez kazanan öğrencilere 10 bin TL eğitim desteği verilmesine ilişkin teklifi meclis gündemine geldi.Gündem maddesini okuduktan sonra Gebze Belediye Başkanı Zinnur Büyükgöz, gençlere daha güçlü bir destek sunmak amacıyla eğitim yardımının artırılmasını önerdi. Başkan Büyükgöz, \"Gelin bunu yüzde 20 artırarak gençlerimize bir jest yapalım.\" ifadelerini kullanarak destek tutarının 12 bin TL\'ye çıkarılmasını teklif etti.Başkan Büyükgöz\'ün önerisi meclis üyelerinin oybirliğiyle kabul edildi. Böylece Gebze Belediyesi, 2026 yılında üniversiteyi ilk kez kazanan öğrencilere kayıtta 12 bin TL eğitim desteği sağlayacak.\r\n\r\n24 Gündem Maddesi Görüşüldü\r\n\r\nAğustos ayı meclis toplantısında, 2\'si önerge olmak üzere toplam 24 gündem maddesi görüşüldü. Toplantıda çeşitli komisyon raporları değerlendirilerek karara bağlandı.\r\n\r\nEmlak ve İstimlak Müdürlüğü\'nün Duraklı Mahallesi 192 ada 1 ve 2 parseller üzerinde irtifak hakkı tesis edilmesine ilişkin Plan ve Bütçe Komisyon Raporu ile Plan ve Proje Müdürlüğü\'nün Pelitli Mahallesi 153 ada 513 parsele ilişkin hazırlanan 1/1000 ölçekli Uygulama İmar Planı Değişikliğine yönelik İmar Komisyon Raporu da oybirliğiyle kabul edildi.\r\n\r\nBir Sonraki Toplantı 1 Eylül\'de\r\n\r\nGebze Belediyesi Meclisi\'nin bir sonraki olağan toplantısının 1 Eylül 2026 Pazartesi günü saat 15.00\'te yapılması kararlaştırıldı', 'img/haberler/meclis.jpg', '2026-08-05 09:00:00'),
(4, 'Gebze Belediyesi Uluslararası Standartlarda', 'Gebze Belediyesi Uluslararası Standartlarda\r\n\r\nGebze Belediyesi, kaynakların verimli kullanılması, enerji performansının sürekli iyileştirilmesi ve çevre odaklı hizmet anlayışı doğrultusunda yürüttüğü çalışmalar sonucunda, uluslararası geçerliliğe sahip ISO 50001 Enerji Yönetim Sistemi Sertifikası’nı almaya hak kazandı.\r\n\r\n\r\n\r\nKurulan sistemle birlikte belediyenin enerji tüketimlerinin anlık olarak takip edilmesi, enerji performansının düzenli şekilde değerlendirilmesi ve tasarruf fırsatlarının belirlenmesi kurumsal ve sürdürülebilir bir yapıya kavuşturuldu.\r\n\r\n\r\n\r\nKocaeli’de Enerji Yönetiminde Öncü Adım\r\n\r\nGebze Belediyesi, Kocaeli genelinde kapsam dahilinde bulunan ilçe belediyeleri arasında ISO 50001 Enerji Yönetim Sistemi Sertifikası’nı alan ilk belediye oldu. Elde edilen bu başarı, Gebze Belediyesi’nin enerji verimliliği, çevre ve sürdürülebilirlik alanlarında ortaya koyduğu çalışmaların önemli bir göstergesi olarak öne çıktı.\r\n\r\n\r\n\r\nISO 50001 standardı doğrultusunda oluşturulan enerji yönetim sistemiyle birlikte, enerji kullanımının yalnızca izlenmesi değil, elde edilen veriler doğrultusunda sürekli iyileştirilmesi ve verimlilik çalışmalarının sistematik hale getirilmesi hedefleniyor.\r\n\r\n\r\n\r\nAnlık Takip ve Veri Odaklı Tasarruf\r\n\r\nSistem kapsamında Ana Hizmet Binası’nın enerji kullanımı düzenli olarak takip edilirken, belediyenin saha tesisleri ve hizmet noktalarındaki enerji tüketimleri de sistematik şekilde izleniyor.\r\n\r\n\r\n\r\nToplanan veriler üzerinden enerji performans göstergeleri değerlendirilerek yüksek tüketim noktaları belirleniyor, tasarruf potansiyelleri analiz ediliyor ve gerekli iyileştirme çalışmaları planlanıyor. Böylece enerji yönetiminde ölçülebilir, veriye dayalı ve sürdürülebilir bir yaklaşım benimseniyor.\r\n\r\n\r\n\r\nEnerji Verimliliğinde Sürekli İyileştirme\r\n\r\nGebze Belediyesi, ISO 50001 Enerji Yönetim Sistemi ile birlikte enerji tüketiminin azaltılmasını, kaynakların daha verimli kullanılmasını ve belediye hizmetlerinde çevresel sürdürülebilirliğin güçlendirilmesini amaçlıyor.\r\n\r\n\r\n\r\nAlınan uluslararası sertifika, Gebze Belediyesi’nin hizmet üretirken kaynakları etkin kullanma ve gelecek nesillere daha yaşanabilir bir kent bırakma hedefi doğrultusunda yürüttüğü çalışmaların kurumsal bir standartla güvence altına alındığını ortaya koyuyor.\r\n', 'img/haberler/seltifika.jpg', '2026-08-13 10:30:00'),
(5, 'Başkan Büyükgöz, Eskihisar Millet Bahçesi ve Botanik Parkı\'nda Vatandaşlarla Bir Araya Geldi', 'Başkan Büyükgöz, Eskihisar Millet Bahçesi ve Botanik Parkı\'nda Vatandaşlarla Bir Araya Geldi\r\n\r\nGebze Belediye Başkanı Zinnur Büyükgöz, şehrin önemli yaşam alanlarından biri olan Eskihisar Millet Bahçesi ve Botanik Parkı\'nı ziyaret ederek hafta sonunu burada geçiren vatandaşlarla bir araya geldi. Parkta aileler, gençler ve çocuklarla sohbet eden Başkan Büyükgöz, vatandaşların talep ve önerilerini dinleyerek onların görüşlerini aldı.Başkan Büyükgöz, park içerisinde yürüyüş yapan vatandaşlarla selamlaşırken çocuklarla da yakından ilgilendi. Yaz akşamlarının vazgeçilmez buluşma noktalarından biri haline gelen Eskihisar Millet Bahçesi ve Botanik Parkı\'nda vatandaşlarla uzun süre sohbet eden Büyükgöz, ailelerle hatıra fotoğrafı da çektirdi.\r\n\r\nVatandaşların Taleplerini Yerinde Dinledi\r\n\r\nZiyareti sırasında vatandaşların belediye hizmetlerine ilişkin görüş ve önerilerini dinleyen Başkan Büyükgöz, devam eden çalışmalar hakkında da bilgi verdi. Mahallelerde yürütülen üstyapı yatırımlarından sosyal ve kültürel projelere kadar birçok konuda vatandaşlarla fikir alışverişinde bulunan Büyükgöz, belediyecilik anlayışlarının merkezinde her zaman insanın yer aldığını ifade etti.\r\n\r\nVatandaşlarla kurdukları güçlü iletişimin hizmet kalitesini artırdığını belirten Başkan Büyükgöz, her fırsatta sahada olmaya ve hemşehrileriyle buluşmaya devam ettiklerini söyledi.\r\n\r\n\"Şehrimizi Birlikte Güzelleştiriyoruz\"\r\n\r\nZiyaretine ilişkin değerlendirmelerde bulunan Gebze Belediye Başkanı Zinnur Büyükgöz, \"Hemşehrilerimizle aynı ortamı paylaşmak, onların görüş ve önerilerini doğrudan dinlemek bizim için son derece kıymetli. Vatandaşlarımızın beklentilerini dikkate alıyor, ortak akıl anlayışıyla hareket ediyoruz. Eskihisar Millet Bahçesi ve Botanik Parkı da ailelerimizin huzurla vakit geçirdiği, çocuklarımızın güvenle oynadığı, doğayla iç içe önemli yaşam alanlarımızdan biri. Bu alanların daha da güzelleşmesi ve vatandaşlarımızın yaşam kalitesinin artması için çalışmalarımızı sürdürüyoruz.\" ifadelerini kullandı.\r\n\r\nVatandaş, Memnuniyetini Dile Getirdi\r\n\r\nVatandaşlar da Başkan Büyükgöz\'ün ziyaretinden duydukları memnuniyeti dile getirerek, kendileriyle yakından ilgilenmesi ve taleplerini dinlemesinden dolayı teşekkür etti. Gebze Belediyesi, vatandaşlarla gönül bağını güçlendiren buluşmalarını ve şehrin yaşam kalitesini artırmaya yönelik çalışmalarını aralıksız sürdürmeye devam ediyor.', 'img/haberler/eskihisar.jpg', '2026-08-04 14:00:00'),
(6, 'Mahallemde Sinema Var Tam Gaz Devam Ediyor', 'Mahallemde Sinema Var Tam Gaz Devam Ediyor\r\n\r\nGebze Belediyesi\'nin yaz akşamlarını renklendiren \"Mahallemde Sinema Var\" etkinlikleri, hafta sonu da çocukları ve aileleri açık havada sinema keyfinde buluşturdu.\r\n\r\nCumartesi günü Cumhuriyet Anadolu Lisesi bahçesinde düzenlenen etkinlikte Cumhuriyet ve Mimar Sinan mahallelerinden vatandaşlar bir araya gelirken, pazar akşamı ise Farabi İlkokulu bahçesinde Adem Yavuz Mahallesi sakinleri yaz akşamının tadını doyasıya çıkardı.\r\n\r\nEtkinlikler ve İkramlar\r\n\r\nHer yaştan vatandaşın yoğun ilgi gösterdiği programlarda çocuklar film gösterimi öncesinde düzenlenen eğlenceli etkinliklerle keyifli vakit geçirirken, aileler de açık havada sinema izlemenin nostaljisini yaşadı. Etkinlik alanlarında vatandaşlara patlamış mısır ikramı da yapıldı.\r\n\r\nYaz Boyunca Devam Edecek\r\n\r\nGebze Belediyesi tarafından düzenlenen \"Mahallemde Sinema Var\" etkinlikleri, yaz boyunca farklı mahallelerde çocukları ve aileleri bir araya getirmeyi sürdürecek. Sinema gösterimlerinin yanı sıra çeşitli ikramlar ve eğlenceli aktivitelerle zenginleşen programlar, mahalle kültürünü güçlendirirken vatandaşlara keyifli yaz akşamları yaşatmaya devam ediyor. ', 'img/haberler/mahallemde-sinema.jpg', '2026-08-04 18:00:00'),
(7, 'Gebze’de Drift Heyecanı', 'Gebze’de Drift Heyecanı\r\n\r\nGebze Belediyesi tarafından bu yıl ikincisi düzenlenen Gebze Drift Festivali, Mevlana Kapalı Pazar Yeri açık otoparkında yoğun katılımla gerçekleştirildi. Özel yapım araçların nefes kesen gösterileri, Gebzelilere adrenalin dolu anlar yaşattı.\r\n\r\nDrift Tutkunları Gebze’de Buluştu\r\n\r\nMotor sporlarına ilgi duyan vatandaşların büyük ilgi gösterdiği festivalde, birbirinden özel olarak hazırlanan araçlar pistte hünerlerini sergiledi. Lastik sesleri ve motorların güçlü performansıyla renklenen etkinlikte sürücülerin gerçekleştirdiği drift gösterileri, izleyenlerden büyük beğeni topladı. Festivali ev sahibi Gebze Belediye Başkanı Zinnur Büyükgöz, Kocaeli Gençli ve Spor İl Müdürü Gökhan Yavaşer, Belediye Başkan Yardımcıları, Belediye Meclis Üyeleri ve çok sayıda Gebzeli takip etti.Festival alanını dolduran Gebzeliler, araçların birbirinden etkileyici şovlarını ilgiyle takip ederken, ortaya çıkan görüntüler heyecan dolu anlara sahne oldu.\r\n\r\nBaşkan Büyükgöz’den Gençlik ve Spor Vurgusu\r\n\r\nFestivale ev sahipliği yapan Gebze Belediye Başkanı Zinnur Büyükgöz, etkinlik kapsamında kısa bir selamlama konuşması gerçekleştirdi. Konuşmasında gençlere ve spora verdikleri öneme dikkat çeken Başkan Büyükgöz, Gebze Belediyesi olarak gençlerin farklı spor branşlarıyla buluşması ve yeteneklerini geliştirmesi için çalışmalar yürüttüklerini ifade etti.\r\n\r\nBüyükgöz, sporun gençlerin fiziksel gelişiminin yanı sıra sosyal ve kültürel gelişimlerine de önemli katkılar sunduğunu belirterek, Gebze’de gençlere yönelik yatırımların ve etkinliklerin artarak devam edeceğini vurguladı.\r\n\r\nGebzelilerden Festivale Yoğun İlgi\r\n\r\nİkinci kez düzenlenen Gebze Drift Festivali, hem motor sporları tutkunlarını hem de farklı bir hafta sonu etkinliği yaşamak isteyen Gebzelileri bir araya getirdi. Özel yapım araçların pistte sergilediği performanslar, izleyenlere unutulmaz bir gösteri sundu.\r\n\r\nGebze’de spor ve gençlik etkinliklerinin önemli buluşmalarından biri haline gelen Drift Festivali, yüksek temposu ve renkli görüntüleriyle kentte adrenalin rüzgârı estirdi.', 'img/haberler/drift.jpg', '2026-08-10 16:00:00'),
(8, 'Gebze Belediyesi Sporcusu Akdeniz Oyunları\'nda Türkiye\'yi Temsil Edecek', 'Gebze Belediyesi Sporcusu Akdeniz Oyunları\'nda Türkiye\'yi Temsil Edecek\r\n\r\nGebze Belediyesi Spor Kulübü sporcusu Alperen Tokgöz, Kocaeli Büyükşehir Belediyesi tarafından düzenlenen Uluslararası Güreş Turnuvası\'nda büyük bir başarıya imza attı.Serbest stil 97 kilogram kategorisinde tüm rakiplerini geride bırakarak şampiyon olan başarılı sporcu, elde ettiği dereceyle Akdeniz Oyunları\'na katılma hakkı kazandı.\r\n\r\nBüyük Başarı\r\n\r\nKBB’nin düzenlediği organizasyonda gösterdiği üstün performansla şampiyonluğa uzanan Alperen Tokgöz, Gebze\'nin gururu oldu. Şampiyonluğuyla Akdeniz Oyunları vizesini alan milli sporcu, ay-yıldızlı formayla ülkemizi temsil etmeye hazırlanıyor.\r\n\r\nBaşkan Büyükgöz\'den Tebrik\r\n\r\nGebze Belediye Başkanı Zinnur Büyükgöz, elde edilen başarıdan duyduğu memnuniyeti dile getirerek şu ifadeleri kullandı:\r\n\r\n\"Gebze Belediyesi olarak spora ve sporcuya yatırım yapmaya devam ediyoruz. Uluslararası turnuvada şampiyon olarak Akdeniz Oyunları\'na katılma hakkı kazanan sporcumuz Alperen Tokgöz\'ü ve emeği geçen antrenörlerimizi yürekten tebrik ediyor, Akdeniz Oyunları\'nda ülkemizi en iyi şekilde temsil edeceğine inanıyorum. Başarılarının devamını diliyorum.\"Gebze Belediyesi Spor Kulübü, farklı branşlarda yetiştirdiği başarılı sporcularla ulusal ve uluslararası arenada önemli dereceler elde etmeyi sürdürürken, Alperen Tokgöz\'ün bu başarısı da Başkan Büyükgöz’ün Sporcu Kent Gebze vizyonunun önemli bir göstergesi oldu.\r\n', 'img/haberler/sporcu.jpg', '2026-08-07 12:00:00'),
(9, 'Köşklüçeşme\'de Açık Hava Sinema Keyfi', 'Köşklüçeşme\'de Açık Hava Sinema Keyfi\r\n\r\nGebze Belediyesi\'nin yaz akşamlarını renklendiren \"Mahallemde Sinema Var\" etkinliği, bu kez Köşklüçeşme Mahallesi\'nde gerçekleştirildi.\r\n\r\nOrhangazi İlkokulu bahçesinde düzenlenen etkinlikte çocuklar ve aileler, sevilen animasyon filmi Rafadan Tayfa: Kapadokya ile keyifli bir yaz akşamı yaşadı.\r\n\r\nÇocuklar Dolu Dolu Bir Akşam Geçirdi\r\n\r\nYaz tatilini birbirinden renkli etkinliklerle değerlendiren çocuklar, açık hava sinema etkinliğinde bir araya geldi. Film gösterimi öncesinde vatandaşlara patlamış mısır ikram edilirken, çocuklar arkadaşlarıyla birlikte eğlenceli anlar yaşadı. Ailelerin de yoğun ilgi gösterdiği programda, mahalle sakinleri yaz akşamının tadını hep birlikte çıkardı.\r\n\r\nMahalle Kültürü Güçleniyor\r\n\r\nGebze Belediyesi tarafından düzenlenen \"Mahallemde Sinema Var\" etkinlikleri, mahalle kültürünü ve komşuluk bağlarını güçlendiriyor. Açık hava sinema buluşmaları, her yaştan vatandaşın bir araya gelmesine vesile oluyor.\r\n\r\nYaz Boyunca Devam Edecek\r\n\r\nGebze Belediyesi\'nin yaz etkinlikleri kapsamında düzenlenen \"Mahallemde Sinema Var\" programı, farklı mahallelerde gerçekleştirilmeye devam edecek. Etkinlik takvimi ve gösterim programına Gebze Belediyesinin resmi internet sitesi ile sosyal medya hesapları üzerinden ulaşılabilecek.', 'img/haberler/acik-hava.jpg', '2026-08-07 11:00:00'),
(10, 'Başkan Büyükgöz, Gebze’nin YKS Şampiyonlarını Ağırladı', 'Başkan Büyükgöz, Gebze’nin YKS Şampiyonlarını Ağırladı\r\n\r\nGebze Belediye Başkanı Zinnur Büyükgöz, Gebze\'de eğitim gören ve 2026 Yükseköğretim Kurumları Sınavı\'nda (YKS) Türkiye genelinde ilk 1000\'e girme başarısı gösteren öğrencileri Gebze Belediyesi\'nde ağırladı.\r\n\r\n\r\n\r\nÖğrenciler ve aileleriyle bir araya gelen Başkan Büyükgöz, gençleri tek tek tebrik ederek eğitim hayatlarında başarılarının devamını diledi.\r\n\r\n\r\n\r\nGüzide Gençlik Merkezi\'nden Büyük Başarı\r\n\r\nGebze Belediyesinin eski adliye binasını restore ederek gençlerin hizmetine sunduğu Güzide Gençlik Merkezi de YKS\'de elde ettiği derecelerle dikkat çekti. Güzide Gençlik Merkezi öğrencilerinden Zehra Nihal Özger, eşit ağırlık puan türünde Türkiye ilk 500\'e girerken, Ömer Talha Aykaç ise sayısal puan türünde Türkiye ilk 600\'e girerek önemli bir başarıya imza attı.\r\n\r\n\r\n\r\nÖğrencilerin başarısından duyduğu memnuniyeti dile getiren Başkan Büyükgöz, “Bu başarılarla birlikte Güzide Gençlik Merkezimiz de kendini kanıtlamış oldu” ifadelerini kullandı.\r\n\r\n\r\n\r\n\"Sevdiğiniz İşin En İyisi Olmaya Gayret Edin\"\r\n\r\nÖğrencilerle samimi bir sohbet gerçekleştiren Başkan Büyükgöz, üniversite hayatının yeni başlangıçların kapısını aralayacağını ifade ederek şu değerlendirmelerde bulundu:\r\n\r\n\r\n\r\n\"Bugün elde ettiğiniz başarı, uzun yıllar süren emeğinizin karşılığıdır. Bundan sonraki eğitim hayatınızda da aynı azim ve kararlılıkla yolunuza devam edin. Hayatta hangi mesleği seçerseniz seçin, sevdiğiniz işi yapın ve yaptığınız işin en iyisi olmaya gayret edin. Bilginizi, birikiminizi ve emeğinizi ülkemizin ve milletimizin geleceği için kullanacağınıza yürekten inanıyorum. Sizler bizim en büyük umudumuz ve en değerli yatırımımızsınız.\"\r\n\r\n\r\n\r\nGençlere Yatırım Sürüyor\r\n\r\nGençlerin akademik, sosyal ve kişisel gelişimlerine katkı sunmak amacıyla hizmet veren Güzide Gençlik Merkezi; akademik destek programlarının yanı sıra robotik ve yazılım atölyeleri, XR laboratuvarı, Teknofest çalışma alanı, sanat atölyeleri, kütüphane, podcast stüdyosu, spor alanları ve rehberlik hizmetleriyle gençlere çok yönlü gelişim imkânı sunmaya devam ediyor.\r\n\r\n\r\n\r\nProgram, öğrenciler ve aileleriyle çekilen hatıra fotoğrafının ardından sona erdi.\r\n', 'img/haberler/yks.jpg', '2026-08-06 09:30:00'),
(11, 'Beş Başkan Şehit Yılmaz Argon Caddesi\'nde', 'Beş Başkan Şehit Yılmaz Argon Caddesi\'nde\r\n\r\nGebze Belediye Başkanı Zinnur Büyükgöz, AK Parti Gebze İlçe Başkanı Recep Kaya, AK Parti Gebze Kadın Kolları Başkanı Habibe Çırak, AK Parti Gebze Gençlik Kolları Başkanı Bilal Durmuş Kurt ve AK Parti Mustafapaşa Mahalle Başkanı Bekir Köse, Mustafapaşa Mahallesi Şehit Yılmaz Argon Caddesi\'nde esnaf ve vatandaşlarla bir araya geldi.\r\n\r\n\r\n\r\nEsnafa Hayırlı İşler Temennisi\r\n\r\nCadde boyunca iş yerlerini tek tek ziyaret eden Başkan Büyükgöz ve beraberindeki heyet, esnafa hayırlı ve bereketli kazançlar dileyerek talep ve önerileri dinledi. Samimi bir atmosferde gerçekleşen ziyaretlerde esnafın beklentileri dinlenirken, bölgedeki ticari hayat ve mahalleye yönelik değerlendirmelerde bulunuldu.\r\n\r\n\r\n\r\nVatandaşlarla Gönül Köprüsü Kuruldu\r\n\r\nCadde üzerinde vatandaşlarla da sohbet eden heyet, mahalle sakinlerinin talep ve önerilerini dinledi. Gerçekleştirilen hasbihallerde belediye hizmetleri, mahallede devam eden çalışmalar ve planlanan projeler üzerine görüş alışverişi yapıldı. Vatandaşların ilettiği talepler ilgili birimlerce değerlendirilmek üzere not alındı.\r\n\r\n\r\n\r\nBaşkan Büyükgöz: \"Yerinde Dinlemeye Devam Edeceğiz\"\r\n\r\nEsnaf ve vatandaşlarla bir araya gelmenin önemine değinen Gebze Belediye Başkanı Zinnur Büyükgöz, \"Esnafımızın güler yüzü, vatandaşlarımızın samimiyeti bizlere güç veriyor. Gebze\'yi ortak akılla yönetmeye, hemşehrilerimizin talep ve önerilerini yerinde dinleyerek çalışmalarımıza yön vermeye devam edeceğiz. Mahallelerimizi yalnızca hizmet götürdüğümüz alanlar olarak değil, gönül bağımızı güçlendirdiğimiz yaşam merkezleri olarak görüyoruz. Vatandaşlarımızla bir araya gelmeyi, onların görüşlerini dinlemeyi ve Gebze\'miz için birlikte üretmeyi sürdüreceğiz.\" ifadelerini kullandı.\r\n\r\n\r\n\r\nŞehit Yılmaz Argon Caddesi\'nde gerçekleşen ziyaret boyunca sıcak ve samimi anlar yaşanırken, esnaf ve vatandaşlar kendilerini dinleyen Başkan Büyükgöz ve beraberindeki heyete teşekkür etti.', 'img/haberler/sehit-yilmaz.jpg', '2026-08-06 13:00:00'),
(12, 'Başkan Büyükgöz\'den Kaymakam Özyiğit\'e Hayırlı Olsun Ziyareti', 'Başkan Büyükgöz\'den Kaymakam Özyiğit\'e Hayırlı Olsun Ziyareti\r\n\r\nGebze Belediye Başkanı Zinnur Büyükgöz, Gebze Millet Bahçesi bitişiğine Gebze Belediyesi tarafından inşa edilerek geçici süreyle Kaymakamlık hizmetine tahsis edilen yeni hizmet binasında görevine devam eden Gebze Kaymakamı Mehmet Ali Özyiğit\'e hayırlı olsun ziyaretinde bulundu.\r\n\r\nYeni Hizmet Binasında İlk Ziyaret\r\n\r\nBaşkan Büyükgöz, Gebze Millet Bahçesi bitişiğinde vatandaşlara hizmet vermeye başlayan geçici Kaymakamlık binasında Kaymakam Mehmet Ali Özyiğit ile bir araya geldi. Samimi bir atmosferde gerçekleşen ziyarette ilçede yürütülen kamu hizmetleri, devam eden yatırımlar ve kurumlar arası koordinasyon üzerine değerlendirmelerde bulunuldu.\r\n\r\nKamu Hizmetlerinde Güçlü İş Birliği\r\n\r\nZiyaret sırasında Gebze\'de devam eden projeler ve vatandaşlara sunulan hizmetlerin daha etkin yürütülmesine yönelik fikir alışverişi yapıldı. Kurumlar arasındaki güçlü iş birliğinin önemine vurgu yapılan görüşmede, ortak akıl ve koordinasyon içerisinde çalışmanın Gebze\'nin gelişimine önemli katkılar sunduğu ifade edildi.\r\n\r\n\"Gebze\'mize Hayırlı Olsun\"\r\n\r\nZiyarette konuşan Gebze Belediye Başkanı Zinnur Büyükgöz, \"Gebze\'mize daha nitelikli hizmet sunabilmek adına kamu kurumlarımızla uyum içerisinde çalışmayı sürdürüyoruz. Gebze Belediyesi olarak inşa ederek Kaymakamlığımızın kullanımına sunduğumuz geçici hizmet binasının ilçemize ve hemşehrilerimize hayırlı olmasını temenni ediyorum.\" dedi.\r\n\r\nKaymakam Özyiğit\'ten Teşekkür\r\n\r\nGebze Kaymakamı Mehmet Ali Özyiğit ise nazik ziyaretinden dolayı Başkan Büyükgöz\'e teşekkür ederek, kamu kurumları arasındaki iş birliği ve dayanışmanın vatandaşlara sunulan hizmetlerin kalitesini artırdığını ifade etti. Kaymakam Özyiğit, yeni hizmet binasında vatandaşlara en iyi şekilde hizmet sunmak için çalışmalarını sürdüreceklerini belirtti.\r\n\r\nOrtak Hizmet Anlayışı Sürüyor\r\n\r\nZiyaret, karşılıklı iyi dileklerin paylaşılması ve günün anısına çekilen hatıra fotoğrafının ardından sona erdi. Gebze Belediyesi ile Kaymakamlık arasındaki güçlü koordinasyonun, ilçeye kazandırılacak yeni yatırımlar ve kamu hizmetlerinde de aynı anlayışla devam edeceği vurgulandı.', 'img/haberler/kaymakam.jpg', '2026-07-26 10:00:00'),
(13, 'Gebze’de Yaz Okulları Coşkuyla Tamamlandı', 'Gebze’de Yaz Okulları Coşkuyla Tamamlandı\r\n\r\nGebze Müftülüğü tarafından düzenlenen ve Gebze Belediyesi’nin de paydaşları arasında yer aldığı Yaz Okulları, Gebze Millet Bahçesi’nde gerçekleştirilen kapanış programıyla sona erdi. Yaz dönemi boyunca yaklaşık 13 bin 500 öğrenciye ulaşılırken, çocuklar ve gençler eğitim, kültür ve çeşitli etkinliklerle dolu bir yaz geçirdi.\r\n\r\n\r\n\r\nKapanış programına Kocaeli Vali Yardımcısı Salih Bıçak, Gebze Kaymakamı Mehmet Ali Özyiğit, Gebze Belediye Başkanı Zinnur Büyükgöz, Gebze İlçe Müftüsü İbrahim Hamarat, Gebze İlçe Protokolü, öğrenciler, aileleri ve vatandaşlar katıldı.\r\n\r\n\r\n\r\nİstiklal Marşı ve Kur’an-ı Kerim Tilaveti\r\n\r\nProgram, İstiklal Marşı’nın okunmasıyla başladı. İstiklal Marşı’nın işaret diliyle de okunması programa anlam kattı. Ardından Kur’an-ı Kerim tilaveti gerçekleştirildi.\r\n\r\n\r\n\r\nKapanış programında yaz okullarına katılan öğrencilerin hazırladığı gösteriler de sahnelendi. Öğrencilerin ilahi dinletisi katılımcılardan büyük beğeni toplarken, mehter takımının gösterisi de programa renk kattı.\r\n\r\n\r\n\r\nÖğrenciler Yaz Tatilini Verimli Geçirdi\r\n\r\nYaz dönemi boyunca gerçekleştirilen eğitim ve etkinliklerle öğrencilerin dini ve milli değerlerle buluşmalarının yanı sıra kişisel, sportif ve kültürel gelişimlerine katkı sağlandı. Çocuklar ve gençler, farklı alanlarda düzenlenen çalışmalar sayesinde yaz tatillerini hem öğrenerek hem de eğlenerek değerlendirme fırsatı buldu.\r\n\r\n\r\n\r\nMüftü Hamarat: “13 Bin 500 Öğrencimize Hizmet Verdik”\r\n\r\nGebze İlçe Müftüsü İbrahim Hamarat, Yaz Okullarına gösterilen ilgiyi dile getirerek yaklaşık 13 bin 500 öğrenciye ulaştıklarını belirtti.\r\n\r\n\r\n\r\nHamarat, “Yaz boyunca yaklaşık 13 bin 500 öğrencimize hizmet verdik. İnşallah önümüzdeki yıllarda daha fazla evladımıza ulaşmayı ve onların eğitimlerine katkı sunmayı hedefliyoruz.” dedi.\r\n\r\n\r\n\r\nBaşkan Büyükgöz: “Evlatlarımız Geleceğimizdir”\r\n\r\nGebze Belediye Başkanı Zinnur Büyükgöz, çocukların ve gençlerin geleceğin teminatı olduğunu vurgulayarak, öğrencilerin milli ve manevi değerlerle yetişmesinin önemine dikkat çekti.\r\n\r\n\r\n\r\nBaşkan Büyükgöz, “Evlatlarımızın milli ve manevi değerlerine bağlı, vatanını ve milletini seven, ülkesine faydalı bireyler olarak yetişmesi en büyük temennimizdir. Onların her alanda kendilerini geliştirmeleri için çalışmalarımızı sürdüreceğiz.” dedi.\r\n\r\n\r\n\r\nKaymakam Özyiğit’ten Öğrencilere Tebrik\r\n\r\nGebze Kaymakamı Mehmet Ali Özyiğit ise Yaz Okullarının düzenlenmesinde emeği geçen kurumlara, eğitmenlere ve ailelere teşekkür etti. Öğrencilere hitap eden Özyiğit, yaz okullarında elde edilen kazanımların eğitim hayatlarına katkı sağlamasını dileyerek, çocukların gelecekte vatana ve millete faydalı bireyler olmaları temennisinde bulundu.\r\n\r\n\r\n\r\nVali Yardımcısı Bıçak: “Alkışlanacak Bir İş”\r\n\r\nKocaeli Vali Yardımcısı Salih Bıçak da yaz okullarına katılan öğrencileri tebrik ederek, çocukların yaz tatillerini verimli şekilde değerlendirmelerinin önemli olduğunu ifade etti.\r\n\r\n\r\n\r\nVali Yardımcısı Bıçak, “Çocuklarımızın yaz tatillerindeki vakitlerini dinimizi ve güzel değerlerimizi öğrenmeye ayırmaları gerçekten alkışlanacak bir iştir. Emek verdiler, öğrendiler ve kendilerini geliştirdiler. Bu güzel çalışmada emeği geçen herkesi tebrik ediyorum.” ifadelerini kullandı.\r\n\r\n\r\n\r\nProgram, öğrencilerin hazırladığı gösterilerin sunulmasının ardından sona erdi.\r\n', 'img/haberler/yaz-okulu.jpg\r\n', '2026-08-13 10:19:15');

